/**
 * The rs-core bindings this package wraps.
 *
 * rs-core reaches JavaScript two ways: a wasm build (web and Node) and a
 * native build behind a React Native TurboModule. Both are generated by
 * uniffi-bindgen-react-native with the same API, so js-core is written
 * against that API and the host registers whichever module it loaded.
 * Types come from the generated TypeScript; values from the registered
 * module.
 */
import type * as Generated from '@polycentric/rs-core-wasm/generated';

export type Bindings = Pick<
  typeof Generated,
  | 'HarborClientBuilder'
  | 'StorageConfig'
  | 'SyncStrategy'
  | 'LoginStatus'
  | 'KeyType'
  | 'ClientEvent_Tags'
  | 'aeadKeyCipher'
  | 'generateWrappingKey'
  | 'blobUrls'
  | 'imageProxyUrls'
  | 'resolveAlias'
>;

export type {
  Application,
  BackupCheck,
  BackupInfo,
  Blob,
  ClientEvent,
  ClientListener,
  ClientSnapshot,
  ClientState,
  Content,
  ContentDigest,
  EventBundle,
  EventKey,
  GetServerInfoResponse,
  HarborClientConfig,
  HarborClientLike,
  IdentityState,
  KeyType,
  KeyCipher,
  LegacyEvent,
  LegacyLogin,
  ListEventsArgs,
  LoginId,
  LoginKind,
  LoginOverview,
  LoginStatus,
  PairingInfo,
  PairingSession,
  PendingEventLike,
  PublicKey,
  PublishArgs,
  Query,
  QueryData,
  QueryOpts,
  QueryResult,
  RegisterPushNotificationRequest,
  ReportStatus,
  ServerPushResult,
  StorageConfig,
  SyncStrategy,
  UrlInfoResponse,
} from '@polycentric/rs-core-wasm/generated';

let registered: Bindings | undefined;

/**
 * Register the rs-core bindings. Hosts call this once, before creating a
 * client (`@polycentric/react-native` and the `web`/`node` entry points
 * of this package do it for you).
 */
export function registerBindings(bindings: Bindings): void {
  registered = bindings;
}

/** The registered bindings. Throws if no host registered any. */
export function bindings(): Bindings {
  if (!registered) {
    throw new Error(
      'rs-core bindings are not registered; create the client through a host entry point',
    );
  }
  return registered;
}

/** Copy `bytes` into a fresh ArrayBuffer for the FFI. */
export function toBuffer(bytes: Uint8Array | ArrayBuffer): ArrayBuffer {
  return bytes instanceof ArrayBuffer
    ? bytes
    : (bytes.slice().buffer as ArrayBuffer);
}
